/* Motion Library — shared runtime for every template.
 * A template sets window.TPL = { duration, defaults:{...}, build(D), draw(t, D) } and loads this file.
 * Data priority: template defaults < window.SEP_DATA (renderer) < ?data={json} (gallery).
 * Canvas is always 1080x1920 (vertical reel). Transparent background. */
(function () {
  // fonts: every family in ../fonts (see fonts/fonts.css, generated by tools/build_fonts.py)
  const lk = document.createElement('link'); lk.rel = 'stylesheet'; lk.href = '../fonts/fonts.css';
  const cssReady = new Promise((r) => { lk.onload = lk.onerror = r; });
  document.head.appendChild(lk);
  const T = window.TPL;
  const Q = new URLSearchParams(location.search);
  let qd = {};
  try { if (Q.get('data')) qd = JSON.parse(Q.get('data')); } catch (e) { console.warn('bad ?data', e); }
  const D = Object.assign({ accent: '#E8835F', font: 'Readex Pro', textColor: '#FAFAFA', y: null }, T.defaults, window.SEP_DATA || {}, qd);
  const st = document.createElement('style');
  st.textContent = `
:root{--accent:${D.accent};--fg:${D.textColor};--font:'${D.font}','Readex Pro',sans-serif;--mono:'Geist Mono',ui-monospace,monospace}
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1080px;height:1920px;background:transparent;overflow:hidden}
body{font-family:var(--font);color:var(--fg);-webkit-font-smoothing:antialiased}
.a{position:absolute}.mono{font-family:var(--mono)}
.ar{direction:rtl;font-variant-ligatures:no-discretionary-ligatures}
.num{direction:ltr;font-weight:600;letter-spacing:-.03em}
.glass{background:rgba(13,13,13,.94);border:2px solid #262626;border-radius:30px;box-shadow:0 40px 120px rgba(0,0,0,.85)}
.acc{color:var(--accent)}
`;
  document.head.appendChild(st);

  const cl = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
  const ML = window.ML = {
    D, cl,
    P: (t, a, b) => cl((t - a) / (b - a)),
    L: (a, b, x) => a + (b - a) * x,
    eo: (x) => 1 - Math.pow(1 - x, 3),
    e4: (x) => 1 - Math.pow(1 - x, 4),
    eio: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
    ex: (x) => (x >= 1 ? 1 : 1 - Math.pow(2, -10 * x)),
    back: (x) => { const c = 1.70158, c3 = c + 1; return 1 + c3 * Math.pow(x - 1, 3) + c * Math.pow(x - 1, 2); },
    vis(el, o, tr) { el.style.opacity = o; el.style.visibility = o <= 0.001 ? 'hidden' : 'visible'; if (tr !== undefined) el.style.transform = tr; },
    blur(el, px) { el.style.filter = px > 0.2 ? `blur(${px.toFixed(1)}px)` : 'none'; },
    $: (id) => document.getElementById(id),
    esc: (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])),
    /* "*word*" -> accent colour */
    rich: (s) => ML.esc(s).replace(/\*([^*]+)\*/g, '<span class="acc">$1</span>'),
    /* rise + de-blur in, lift + blur out — the motion the reels use */
    riseIn(el, t, a, b, dy = 42) {
      const x = ML.e4(ML.P(t, a, a + 0.7)), fi = ML.eo(ML.P(t, a, a + 0.45)), o = ML.eio(ML.P(t, b - 0.35, b));
      el.style.opacity = Math.min(fi, 1 - o);
      el.style.transform = `translateY(${ML.L(dy, 0, x) - o * 26}px) scale(${ML.L(0.97, 1, x)})`;
      ML.blur(el, ML.L(14, 0, x) + o * 12);
    },
    ring(ctx, t, T0, cx, cy, dur = 0.8, r0 = 40, r1 = 220) {
      if (t < T0 || t > T0 + dur) return; const k = ML.P(t, T0, T0 + dur);
      ctx.globalAlpha = (1 - k) * 0.6; ctx.strokeStyle = D.accent; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(cx, cy, r0 + ML.eo(k) * (r1 - r0), 0, 7); ctx.stroke(); ctx.globalAlpha = 1;
    },
    burst(ctx, t, T0, cx, cy, dur = 1) {
      if (t < T0 || t > T0 + dur) return; const k = ML.P(t, T0, T0 + dur);
      for (let i = 0; i < 40; i++) { const a = i * 2.4 + T0, v = (170 + ((i * 97) % 260)) * ML.eo(k); ctx.globalAlpha = 1 - k; ctx.fillStyle = i % 3 ? D.accent : '#fff'; ctx.beginPath(); ctx.arc(cx + Math.cos(a) * v, cy + Math.sin(a) * v * 0.9, (3 + (i % 5)) * (1 - k * 0.5), 0, 7); ctx.fill(); }
      ctx.globalAlpha = 1;
    },
  };
  ML.dur = D.duration || T.duration;

  const boot = () => {
    T.build && T.build(D);
    window.SEP_seek = (t) => { T.draw(t, D); return { empty: false }; };
    window.SEP_ready = () => cssReady.then(() => document.fonts.load(`700 40px '${D.font}'`)).then(() => document.fonts.ready);
    window.SEP_info = () => ({ duration: ML.dur });
    T.draw(0, D);
    // gallery / browser preview: loop the animation when not driven by the renderer
    if (!window.SEP_DATA && !Q.has('still')) {
      document.body.style.background = Q.get('bg') || 'transparent';
      const t0 = performance.now(), loop = ML.dur + 0.8;
      const tick = () => { T.draw(((performance.now() - t0) / 1000) % loop, D); requestAnimationFrame(tick); };
      cssReady.then(() => document.fonts.ready).then(() => requestAnimationFrame(tick));
    }
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', boot) : boot();
})();
